func TestWriteResponseSanitizesControlCharactersInAllDiagnosticText(t *testing.T) {
	response := Response{
		ProtocolVersion: 1,
		Decision:        "block",
		Reason:          "first line\nforged line\tend",
		Findings: []Finding{{
			RuleID:   "scanner.\x00rule",
