	})
	if err != nil {
		t.Fatal(err)
	}
	result := artifact.Scanners["cisco"]
	if result.Status != "completed" {
		t.Fatalf("status = %q error = %q", result.Status, result.Error)
	}
	if !bytes.Equal(result.Raw, []byte(ciscoJSON)) {
		t.Fatalf("raw = %s", result.Raw)
